"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8831],{68831:a=>{a.exports=JSON.parse('{"slug":"dollar-86-rubley-minfin-pokupki-valyuty","locale":"ru","title":"Доллар поднялся выше 86 рублей: Минфин в 5 раз увеличивает покупки валюты","description":"Доллар 6 октября превысил 86 рублей: Минфин с 7 октября покупает валюту на 12,7 млрд рублей в день. Как цена нефти через бюджетное правило ослабляет рубль.","blocks":[{"id":"b001","kind":"paragraph","text":"Утром 6 октября доллар на внебиржевом рынке стоил до 86,1 рубля. Выше 86 он не поднимался с 9 сентября. Евро подорожал на 0,6%, до 96,3 рубля, юань на 0,7%, до 12,8 рубля. Официальный курс Банк России считает по торгам предыдущего дня, поэтому на 6 октября он ниже: 84,93 рубля, на 1,45 рубля больше, чем днём раньше. 1 октября официальный курс был 83,56 рубля. В мире доллар 5 октября, наоборот, дешевел, так что рубль слабеет по своим причинам."},{"id":"b002","kind":"paragraph","text":"5 октября Минфин объявил, что с 7 октября по 6 ноября купит валюту и золото на 279,42 млрд рублей, по 12,7 млрд в день. В прошлый месяц он тратил на это 2,5 млрд в день. Банк России параллельно продаёт валюту на 0,58 млрд рублей в день, и за вычетом его продаж государство будет покупать на 12,12 млрд в день. В сентябре выходило 1,92 млрд, разница в 6,3 раза. Больше государство не покупало с начала 2022 года. Покупки начнутся только 7 октября, но рынок отреагировал уже на объявление."},{"id":"b003","kind":"paragraph","text":"Деньги на покупки дала нефть. Бюджет России рассчитан на Urals по $59 за баррель. Если нефть дороже, налоги с разницы государство не тратит, а кладёт в Фонд национального благосостояния, покупая валюту и золото. Эту планку называют ценой отсечения. Нефтяники платят налоги с задержкой на месяц: в октябре платят за сентябрь. В августе Urals стоила $67,11, ненамного выше планки. В сентябре $92,08, и в октябре Минфин ждёт 289,46 млрд рублей сверх плана. Купит он на 279,42 млрд: 10,04 млрд вычел, потому что в сентябре доходы оказались ниже его оценки."},{"id":"b004","kind":"paragraph","text":"Само по себе правило рубль двигать не должно. Нефтяники продают больше валюты, чтобы заплатить выросшие налоги, а Минфин эту валюту выкупает. Загвоздка в сроках. Минфин покупает каждый день равными частями, начиная с 7 октября, а экспортёры больше всего продают в конце месяца, перед уплатой налогов. В первые недели покупателей на рынке больше, чем продавцов, и рубль дешевеет. Добавляют и праздники в Китае до 7 октября: сделок с юанем мало, и крупная покупка сильнее сдвигает курс."},{"id":"b005","kind":"paragraph","text":"Если рубль продолжит слабеть, это дойдёт до цен на поездки, технику и машины, которые завязаны на валюту. С 1 по 6 октября официальный курс доллара вырос на 1,6%. Поддерживает рубль ключевая ставка Банка России, 14%: под такую ставку рублёвые вклады выгоднее валютных. Обычно рубль поддерживают и экспортёры в конце месяца, когда продают валюту на налоги. Насколько их продажи перекроют покупки Минфина, сейчас сказать нельзя."},{"id":"b006","kind":"paragraph","text":"Для тех, кто собирается менять рубли на валюту, важны сроки. Сейчас курс поднят месячной программой покупок, которая закончится 6 ноября. Но если нефть в октябре останется дорогой, в ноябре покупки снова будут большими: ноябрьские налоги посчитают по октябрьской цене."},{"id":"b007","kind":"heading","text":"Почему доллар подорожал в октябре 2026 года?"},{"id":"b008","kind":"paragraph","text":"Минфин с 7 октября будет покупать валюту и золото на 12,7 млрд рублей в день, в 5 раз больше, чем в сентябре. Крупный покупатель на бирже толкает цену валюты вверх, и рынок отреагировал уже на объявление: 6 октября доллар впервые с 9 сентября поднялся выше 86 рублей."},{"id":"b009","kind":"heading","text":"Что такое цена отсечения в бюджетном правиле?"},{"id":"b010","kind":"paragraph","text":"Это цена нефти, на которую рассчитан бюджет, в 2026 году $59 за баррель. Налоги от нефти сверх этой цены государство не тратит, а откладывает в Фонд национального благосостояния, покупая валюту и золото."},{"id":"b011","kind":"heading","text":"Сколько Минфин будет покупать валюту в таком объёме?"},{"id":"b012","kind":"paragraph","text":"Текущий объём действует с 7 октября по 6 ноября. Новый объём Минфин объявит в начале ноября, и он будет зависеть от цены нефти в октябре."}],"sources":[{"label":"Минфин с 7 октября увеличит покупку валюты/золота в пять раз","url":"https://www.interfax.ru/business/1120386"},{"label":"Минфин купит валюту и золото на 279,42 млрд руб. с 7 октября по 6 ноября","url":"https://www.kommersant.ru/doc/9006327"},{"label":"Минфин и ЦБР нарастят покупки валюты в октябре более чем в 6 раз","url":"https://ru.themoscowtimes.com/2026/10/05/update-1-minfin-i-tsbr-narastyat-pokupki-valyuty-v-oktyabre-bolee-chem-v-6-raz-do-1212-mlrd-r-v-den-a207802"},{"label":"Курс доллара превысил 86 рублей впервые с 9 сентября","url":"https://www.kommersant.ru/doc/9007053"},{"label":"Рубль утром дешевеет к юаню","url":"https://www.interfax.ru/business/1120563"},{"label":"ЦБ повысил официальный курс доллара почти на ₽1,5","url":"https://finance.mail.ru/article/tsb-povyisil-ofitsialnyij-kurs-dollara-pochti-na-15-69231003/"},{"label":"Официальный курс доллара опустился ниже 84 рублей","url":"https://www.vedomosti.ru/finance/news/2026/09/30/1233185-kurs-opustilsya"},{"label":"Новая цена отсечения для нефтяных доходов","url":"https://www.fontanka.ru/2026/09/09/76634061/"},{"label":"Urals в сентябре подорожала на Балтике, в Индии и КНР","url":"https://www.interfax.ru/business/1119753"},{"label":"Stocks upbeat, dollar wobbles as Fed hike bets recede","url":"https://finance.yahoo.com/markets/stocks/articles/stocks-upbeat-dollar-wobbles-fed-012516671.html"},{"label":"Банк России сохранил ключевую ставку на уровне 14%","url":"https://www.cbr.ru/press/keypr/"}],"sourceBodySha256":"b900eb1904932c64959784d06618a3e247429cc6ba8713c6bd8f0558bb9d2f88"}')}}]);